package ir

import (
	"fmt"
	"regexp"
	"sort"
	"strings"
)

var scalarIdentitySegmentPattern = regexp.MustCompile(`^[A-Z][A-Za-z0-9]*$`)

const (
	// Legacy and canonical UUID scalar identities.
	LegacyUUIDScalarName    = "UUID"
	CanonicalUUIDScalarName = "Identity.UUID"

	// LegacyIDScalarName is the legacy "ID" scalar identity, recognized for
	// @autoGenerated support on hand-migrated schemas.
	LegacyIDScalarName = "ID"

	// Legacy and canonical DateTime scalar identities.
	LegacyDateTimeScalarName    = "DateTime"
	CanonicalDateTimeScalarName = "Temporal.DateTime"
)

// ValidateCanonicalScalarName validates canonical scalar identity.
//
// Canonical names must be either:
//   - Legacy flat name: Segment
//   - Namespaced name: Segment.Segment[.Segment...]
//
// Each segment must be PascalCase.
func ValidateCanonicalScalarName(name string) error {
	if name == "" {
		return fmt.Errorf("canonical scalar name is empty")
	}

	segments := strings.Split(name, ".")
	for _, segment := range segments {
		if !scalarIdentitySegmentPattern.MatchString(segment) {
			return fmt.Errorf("invalid canonical scalar segment %q in %q", segment, name)
		}
	}

	return nil
}

// IsNamespacedCanonicalScalarName reports whether a canonical name is namespaced.
func IsNamespacedCanonicalScalarName(name string) bool {
	return strings.Count(name, ".") >= 1
}

// IsBuiltinScalar reports whether name is a host-language primitive scalar.
func IsBuiltinScalar(name string) bool {
	switch strings.TrimSpace(name) {
	case "String", "Int", "Float", "Boolean", "ID":
		return true
	default:
		return false
	}
}

// ResolveScalarCanonicalName returns a canonical scalar identity from either
// a type reference name or the scalar definition metadata.
//
// Priority:
//  1. scalarDef.Name when present
//  2. trimmed typeName fallback
func ResolveScalarCanonicalName(typeName string, scalarDef *ScalarDef) string {
	if scalarDef != nil && strings.TrimSpace(scalarDef.Name) != "" {
		return strings.TrimSpace(scalarDef.Name)
	}
	return strings.TrimSpace(typeName)
}

// IsUUIDScalarName reports whether name is a UUID scalar identity.
func IsUUIDScalarName(name string) bool {
	switch strings.TrimSpace(name) {
	case LegacyUUIDScalarName, CanonicalUUIDScalarName:
		return true
	default:
		return false
	}
}

// IsIDScalarName reports whether name is the legacy ID scalar identity.
func IsIDScalarName(name string) bool {
	return strings.TrimSpace(name) == LegacyIDScalarName
}

// IsDateTimeScalarName reports whether name is a DateTime scalar identity.
func IsDateTimeScalarName(name string) bool {
	switch strings.TrimSpace(name) {
	case LegacyDateTimeScalarName, CanonicalDateTimeScalarName:
		return true
	default:
		return false
	}
}

// IsAutoGeneratedScalar reports whether a scalar supports @autoGenerated.
func IsAutoGeneratedScalar(typeName string, scalarDef *ScalarDef) bool {
	canonicalName := ResolveScalarCanonicalName(typeName, scalarDef)
	return IsUUIDScalarName(canonicalName) ||
		IsIDScalarName(canonicalName) ||
		IsDateTimeScalarName(canonicalName)
}

// ScalarAliasResolutionStatus describes the outcome of scalar alias resolution.
type ScalarAliasResolutionStatus string

const (
	// ScalarAliasResolutionResolved means the input token resolved to one canonical scalar.
	ScalarAliasResolutionResolved ScalarAliasResolutionStatus = "resolved"

	// ScalarAliasResolutionAmbiguous means the input token matched multiple canonical scalars.
	ScalarAliasResolutionAmbiguous ScalarAliasResolutionStatus = "ambiguous"

	// ScalarAliasResolutionNotFound means the input token did not match any known scalar.
	ScalarAliasResolutionNotFound ScalarAliasResolutionStatus = "not_found"
)

// ScalarAliasResolution is the typed result of resolving a scalar token.
type ScalarAliasResolution struct {
	Status        ScalarAliasResolutionStatus
	CanonicalName string
	Candidates    []string
}

// ScalarAliasIndex stores canonical scalar identities and their short aliases.
type ScalarAliasIndex struct {
	canonicalNames map[string]struct{}
	aliases        map[string][]string
}

// CanonicalScalarShortAlias returns the short alias portion of a canonical
// scalar identity.
//
// Examples:
//
//	Identity.Name -> Name
//	UUID -> UUID
func CanonicalScalarShortAlias(canonicalName string) (string, error) {
	trimmed := strings.TrimSpace(canonicalName)
	if err := ValidateCanonicalScalarName(trimmed); err != nil {
		return "", err
	}

	idx := strings.LastIndex(trimmed, ".")
	if idx == -1 {
		return trimmed, nil
	}
	return trimmed[idx+1:], nil
}

// BuildScalarAliasIndex builds a scalar alias index from schema scalar definitions.
func BuildScalarAliasIndex(scalars map[string]*ScalarDef) ScalarAliasIndex {
	index := ScalarAliasIndex{
		canonicalNames: make(map[string]struct{}),
		aliases:        make(map[string][]string),
	}
	if len(scalars) == 0 {
		return index
	}

	aliasToSet := make(map[string]map[string]struct{})
	for mapKey, scalarDef := range scalars {
		canonicalName := strings.TrimSpace(mapKey)
		if scalarDef != nil && strings.TrimSpace(scalarDef.Name) != "" {
			canonicalName = strings.TrimSpace(scalarDef.Name)
		}
		if canonicalName == "" {
			continue
		}

		if err := ValidateCanonicalScalarName(canonicalName); err != nil {
			continue
		}
		index.canonicalNames[canonicalName] = struct{}{}

		alias, err := CanonicalScalarShortAlias(canonicalName)
		if err != nil || alias == "" {
			continue
		}
		candidates, ok := aliasToSet[alias]
		if !ok {
			candidates = make(map[string]struct{})
			aliasToSet[alias] = candidates
		}
		candidates[canonicalName] = struct{}{}
	}

	for alias, candidateSet := range aliasToSet {
		canonicalCandidates := make([]string, 0, len(candidateSet))
		for canonicalName := range candidateSet {
			canonicalCandidates = append(canonicalCandidates, canonicalName)
		}
		sort.Strings(canonicalCandidates)
		index.aliases[alias] = canonicalCandidates
	}

	return index
}

// Resolve resolves a scalar token to a canonical scalar name.
//
// Resolution rules:
//   - Fully namespaced canonical tokens (contains ".") must match exactly.
//   - Non-namespaced tokens are resolved as short aliases.
//   - Ambiguous aliases return all canonical candidates.
func (i ScalarAliasIndex) Resolve(token string) ScalarAliasResolution {
	trimmed := strings.TrimSpace(token)
	if trimmed == "" {
		return ScalarAliasResolution{Status: ScalarAliasResolutionNotFound}
	}

	if strings.Contains(trimmed, ".") {
		if _, ok := i.canonicalNames[trimmed]; ok {
			return ScalarAliasResolution{
				Status:        ScalarAliasResolutionResolved,
				CanonicalName: trimmed,
			}
		}
		return ScalarAliasResolution{Status: ScalarAliasResolutionNotFound}
	}

	candidates := i.aliases[trimmed]
	switch len(candidates) {
	case 0:
		return ScalarAliasResolution{Status: ScalarAliasResolutionNotFound}
	case 1:
		return ScalarAliasResolution{
			Status:        ScalarAliasResolutionResolved,
			CanonicalName: candidates[0],
		}
	default:
		return ScalarAliasResolution{
			Status:     ScalarAliasResolutionAmbiguous,
			Candidates: append([]string(nil), candidates...),
		}
	}
}
